(function(){window.PhysicaRankPyqNeet_chemistry_haloalkanesandhaloarenes=[{id:"neet-2025-q084",pn:84,y:"NEET 2025",tp:"Haloalkanes and Haloarenes",st:"SN2 reaction and leaving group",q:`Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R).
Assertion (A) : a zig-zag alkyl iodide (R\u2013I) undergoes SN2 reaction faster than the zig-zag alkyl chloride (R\u2013Cl).
Reason (R) : Iodine is a better leaving group because of its large size.
In the light of the above statements, choose the correct answer from the options given below:`,o:["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],c:0,s:`Rate of SN2 reaction of the alkyl iodide is faster than that of the alkyl chloride.
Iodine is a good leaving group because of its large size, which stabilises the I\u207B ion.
So both A and R are true and R explains A.`,fig:{w:250,h:40,alt:"Two skeletal zig-zag chains of the same length: one ending in I (alkyl iodide), one ending in Cl (alkyl chloride).",d:[["p","M10 24 L27 14 L44 24 L61 14 L78 24",""],["t",80,28,"I",""],["p","M140 24 L157 14 L174 24 L191 14 L208 24",""],["t",210,28,"Cl",""]]},sfig:{w:250,h:40,alt:"Two skeletal zig-zag chains: one ending in I (alkyl iodide), one ending in Cl (alkyl chloride).",d:[["p","M10 22 L27 12 L44 22 L61 12 L78 22",""],["t",80,26,"I",""],["p","M140 22 L157 12 L174 22 L191 12 L208 22",""],["t",210,26,"Cl",""]]}},{id:"neet-2024-q076",pn:76,y:"NEET 2024 \xB7 5 May",tp:"Haloalkanes and Haloarenes",st:"SN1 reactivity",q:"The compound that will undergo SN1 reaction with the fastest rate is",o:["(bromobenzene)","(1-bromoethyl)benzene","(bromomethyl)cyclohexane","bromocyclohexane"],c:1,s:`SN1 reactivity depends on the stability of the carbocation formed.
Stability order: C\u2086H\u2085\u2013CH\u207A\u2013CH\u2083 (benzylic, secondary) > cyclohexyl cation > cyclohexyl\u2013CH\u2082\u207A > phenyl cation.
So (1-bromoethyl)benzene, C\u2086H\u2085\u2013CH(Br)\u2013CH\u2083, is the most reactive.`,fig:{w:330,h:160,alt:"Four structures: (1) bromobenzene, (2) 1-bromoethylbenzene, (3) bromomethylcyclohexane, (4) bromocyclohexane",d:[["t",4,40,"(1)","s"],["p","M76 36 L68 49.9 L52 49.9 L44 36 L52 22.1 L68 22.1 Z",""],["l",71.6,37.5,67.1,45.3,""],["l",52.9,45.3,48.4,37.5,""],["l",55.5,25.2,64.5,25.2,""],["l",76,36,92,36,""],["t",104,40,"Br","m"],["t",170,40,"(2)","s"],["p","M242 36 L234 49.9 L218 49.9 L210 36 L218 22.1 L234 22.1 Z",""],["l",237.6,37.5,233.1,45.3,""],["l",218.9,45.3,214.4,37.5,""],["l",221.5,25.2,230.5,25.2,""],["l",242,36,254,36,""],["t",260,40,"C","m"],["l",260,28,260,16,""],["t",260,12,"CH\u2083","m"],["l",267,36,280,36,""],["t",292,40,"Br","m"],["t",4,124,"(3)","s"],["p","M76 120 L68 133.9 L52 133.9 L44 120 L52 106.1 L68 106.1 Z",""],["l",76,120,90,130,""],["l",90,130,104,122,""],["t",116,128,"Br","m"],["t",170,124,"(4)","s"],["p","M242 120 L234 133.9 L218 133.9 L210 120 L218 106.1 L234 106.1 Z",""],["l",242,120,258,120,""],["t",270,124,"Br","m"]]},sfig:{w:360,h:120,alt:"Carbocation stability: benzylic secondary cation greater than cyclohexyl cation greater than cyclohexylmethyl cation greater than phenyl cation; the answer is C6H5-CH(Br)-CH3",d:[["p","M15 14 L23.7 19 L23.7 29 L15 34 L6.3 29 L6.3 19 Z",""],["l",15.9,16.7,20.8,19.6,""],["l",20.8,28.4,15.9,31.3,""],["l",8.2,26.8,8.2,21.2,""],["t",55.1,28,"CH\u207A\u2013CH\u2083","m"],["t",83.5,28,">","m"],["p","M99.8 14 L108.5 19 L108.5 29 L99.8 34 L91.1 29 L91.1 19 Z",""],["t",120.1,28,"\u207A","m"],["t",128.7,28,">","m"],["p","M145 14 L153.7 19 L153.7 29 L145 34 L136.3 29 L136.3 19 Z",""],["t",178.5,28,"\u2013CH\u2082\u207A","m"],["t",200.3,28,">","m"],["p","M216.6 14 L225.3 19 L225.3 29 L216.6 34 L207.9 29 L207.9 19 Z",""],["l",217.5,16.7,222.4,19.6,""],["l",222.4,28.4,217.5,31.3,""],["l",209.8,26.8,209.8,21.2,""],["t",236.9,28,"\u207A","m"],["t",4,64,"Fastest SN1:","s"],["p","M15 84 L23.7 89 L23.7 99 L15 104 L6.3 99 L6.3 89 Z",""],["l",15.9,86.7,20.8,89.6,""],["l",20.8,98.4,15.9,101.3,""],["l",8.2,96.8,8.2,91.2,""],["t",65,98,"CH(Br)\u2013CH\u2083","m"]]}},{id:"neet-2024-q099",pn:99,y:"NEET 2024 \xB7 5 May",tp:"Haloalkanes and Haloarenes",st:"Alcohol to haloalkane and elimination",q:`Major product A and B formed in the following reaction sequence, are
(cyclohexane ring with OH and a CH\u2083 on adjacent carbons) \u2014PBr\u2083\u2192 A (major) \u2014alc. KOH, \u0394\u2192 B (major)`,o:["A = ring with OH (top) and CH\u2083 and Br on the ring; B = ring with OH and a C=C","A = ring with OH, CH\u2083 and Br; B = 2-methylcyclohexanone","A = ring with CH\u2083 and Br (no OH); B = ring with CH\u2083 on a C=C (methylcyclohexene, double bond at the CH\u2083-bearing carbon)","A = ring with CH\u2083 and Br (no OH); B = ring with a C=C not at the CH\u2083 carbon"],c:2,s:`PBr\u2083 replaces the OH group by Br, so A is the bromo compound.
Alcoholic KOH on heating removes HBr (dehydrohalogenation, base takes the H).
The more substituted alkene is the major product (Saytzeff rule).
So B has the double bond carrying the CH\u2083 group.`,fig:{w:445,h:245,alt:"2-methylcyclohexanol with PBr3 gives A, then alcoholic KOH with heat gives B. Options (1)-(4) each show structures A and B: (1) bromo-hydroxy compound and cyclohexenol, (2) bromo-hydroxy compound and 2-methylcyclohexanone, (3) 1-bromo-2-methylcyclohexane and 1-methylcyclohexene, (4) 1-bromo-2-methylcyclohexane and 4-methylcyclohexene with ring C=C away from the methyl carbon.",d:[["p","M48 40L61 47.5L61 62.5L48 70L35 62.5L35 47.5Z"],["l",35,47.5,24.6,41.5],["t",25.6,45.5,"H\u2083C","e"],["l",48,40,48,29,""],["t",48,26,"OH","m"],["l",85,55,135,55,"a"],["t",110,48,"PBr\u2083","ms"],["t",160,53,"A","m"],["t",160,65,"(major)","ms"],["l",185,55,245,55,"a"],["t",215,48,"alc. KOH","ms"],["t",215,68,"\u0394","ms"],["t",272,53,"B","m"],["t",272,65,"(major)","ms"],["t",4,144,"(1) A ="],["p","M85 125L98 132.5L98 147.5L85 155L72 147.5L72 132.5Z"],["l",72,132.5,61.6,126.5],["t",62.6,130.5,"H\u2083C","e"],["l",85,125,85,114,""],["t",85,111,"OH","m"],["l",98,132.5,108.4,126.5],["t",107.4,130.5,"Br"],["t",124,144,"; B ="],["p","M203 125L216 132.5L216 147.5L203 155L190 147.5L190 132.5Z"],["l",190,132.5,179.6,126.5],["t",180.6,130.5,"H\u2083C","e"],["l",203,125,203,114,"B"],["t",203,111,"OH","m"],["l",212.5,134.8,212.5,145.3],["t",229,144,"(2) A ="],["p","M310 125L323 132.5L323 147.5L310 155L297 147.5L297 132.5Z"],["l",297,132.5,286.6,126.5],["t",287.6,130.5,"H\u2083C","e"],["l",310,125,310,114,""],["t",310,111,"OH","m"],["l",323,132.5,333.4,126.5],["t",332.4,130.5,"Br"],["t",349,144,"; B ="],["p","M428 125L441 132.5L441 147.5L428 155L415 147.5L415 132.5Z"],["l",415,132.5,404.6,126.5],["t",405.6,130.5,"H\u2083C","e"],["l",426.2,125,426.2,114],["l",429.8,125,429.8,114],["t",428,111,"O","m"],["t",4,219,"(3) A ="],["p","M85 200L98 207.5L98 222.5L85 230L72 222.5L72 207.5Z"],["l",72,207.5,61.6,201.5],["t",62.6,205.5,"H\u2083C","e"],["l",85,200,85,189],["t",85,186,"Br","m"],["t",124,219,"; B ="],["p","M203 200L216 207.5L216 222.5L203 230L190 222.5L190 207.5Z"],["l",190,207.5,179.6,201.5],["t",180.6,205.5,"H\u2083C","e"],["l",193.7,209.4,202.8,204.2],["t",229,219,"(4) A ="],["p","M310 200L323 207.5L323 222.5L310 230L297 222.5L297 207.5Z"],["l",297,207.5,286.6,201.5],["t",287.6,205.5,"H\u2083C","e"],["l",310,200,310,189],["t",310,186,"Br","m"],["t",349,219,"; B ="],["p","M428 200L441 207.5L441 222.5L428 230L415 222.5L415 207.5Z"],["l",415,207.5,404.6,201.5],["t",405.6,205.5,"H\u2083C","e"],["l",437.5,209.8,437.5,220.3]]},sfig:{w:290,h:200,alt:"Alcohol with PBr3 gives bromo compound A; the base removes the H on the carbon bearing CH3 while Br leaves, giving B, 1-methylcyclohexene with the C=C at the carbon carrying CH3.",d:[["p","M45 37L58 44.5L58 59.5L45 67L32 59.5L32 44.5Z"],["l",32,44.5,21.6,38.5],["t",22.6,42.5,"H\u2083C","e"],["l",45,37,45,26,""],["t",45,23,"OH","m"],["l",85,52,140,52,"a"],["t",112,45,"PBr\u2083","ms"],["p","M205 37L218 44.5L218 59.5L205 67L192 59.5L192 44.5Z"],["l",205,37,205,26],["t",207,22,"Br"],["l",192,44.5,182,35.5],["t",181,34,"H\u2083C","e"],["l",192,44.5,182,54,""],["t",176,66,"H","m"],["p","M202 20C193 21 191 11 198 8","a"],["p","M178 90C169 85 168 82 173 76","a"],["t",180,102,"Base","m"],["t",252,52,"(A)","m"],["t",252,64,"major","ms"],["l",207,80,207,112,"a"],["p","M207 125L220 132.5L220 147.5L207 155L194 147.5L194 132.5Z"],["l",194,132.5,184,126],["l",197.7,134.4,206.8,129.2],["t",207,178,"(B)","m"],["t",207,190,"major","ms"]]}},{id:"neet-2023-q084",pn:84,y:"NEET 2023 \xB7 7 May",tp:"Haloalkanes and Haloarenes",st:"Classification of haloalkanes",q:"The given compound C\u2086H\u2085\u2013CH=CH\u2013CH(X)\u2013CH\u2082CH\u2083 (the halogen X is on the carbon next to the C=C) is an example of __________.",o:["Vinylic halide","Benzylic halide","Aryl halide","Allylic halide"],c:3,s:`The carbon bearing X is sp\xB3 and sits right next to a C=C.
That position is called the allylic position.
So the compound is an allylic halide.`,fig:{w:215,h:125,alt:"A benzene ring attached to the chain CH=CH-CH(X)-CH2CH3: a double bond, then a carbon bearing the halogen X, then an ethyl group.",d:[["t",38,34,"CH","m"],["t",78,34,"CH","m"],["t",118,34,"CH","m"],["t",162,34,"CH\u2082CH\u2083","m"],["l",48,32.6,68,32.6,""],["l",48,27.4,68,27.4,""],["l",88,30,108,30,""],["l",128,30,140.2,30,""],["l",38,70,57.1,81,""],["l",57.1,81,57.1,103,""],["l",57.1,103,38,114,""],["l",38,114,18.9,103,""],["l",18.9,103,18.9,81,""],["l",18.9,81,38,70,""],["c",38,92,13,""],["l",38,70,38,39,""],["l",118,39,118,54,""],["t",118,66,"X","m"]]}},{id:"neet-2023-q093",pn:93,y:"NEET 2023 \xB7 7 May",tp:"Haloalkanes and Haloarenes",st:"Wurtz-Fittig reaction",q:`Identify the final product [D] obtained in the following sequence of reactions.
CH\u2083CHO \u2192 [A] (i) LiAlH\u2084, (ii) H\u2083O\u207A; [A] \u2192 [B] with H\u2082SO\u2084, \u0394; [B] \u2192 [C] with HBr; [C] + bromobenzene \u2192 [D] with Na/dry ether`,o:["HC\u2261C\u207BNa\u207A","(2)","(3)","C\u2084H\u2081\u2080"],c:1,s:`LiAlH\u2084 reduces CH\u2083CHO to ethanol, CH\u2083CH\u2082OH [A].
H\u2082SO\u2084 with heat dehydrates it to ethene, CH\u2082=CH\u2082 [B].
HBr adds to give bromoethane, CH\u2083CH\u2082Br [C].
With bromobenzene and Na in dry ether (Wurtz-Fittig reaction), the ethyl and phenyl groups join.
[D] is ethylbenzene.`,fig:{w:450,h:215,alt:"Reaction scheme: CH3CHO with LiAlH4 then H3O+ gives A, H2SO4 and heat gives B, HBr gives C, and C with bromobenzene and Na in dry ether gives D; options are HC\u2261C\u207BNa\u207A, ethylbenzene, biphenyl and C4H10.",d:[["t",4,88,"CH\u2083CHO",""],["l",58,80,122,80,"a"],["t",90,72,"(i)LiAlH\u2084","ms"],["t",90,96,"(ii)H\u2083O\u207A","ms"],["t",126,88,"[A]",""],["l",152,80,202,80,"a"],["t",177,74,"H\u2082SO\u2084","ms"],["t",177,96,"\u0394","ms"],["t",208,88,"[B]",""],["l",234,80,276,80,"a"],["t",255,74,"HBr","ms"],["t",282,88,"[C]",""],["l",308,80,420,80,"a"],["t",364,96,"Na/dry ether","ms"],["t",426,88,"[D]",""],["l",352,23,361.5,28.5,""],["l",354.2,26.5,357.5,28.4,""],["l",361.5,28.5,361.5,39.5,""],["l",361.5,39.5,352,45,""],["l",357.5,39.7,354.2,41.6,""],["l",352,45,342.5,39.5,""],["l",342.5,39.5,342.5,28.5,""],["l",344.4,35.9,344.4,32.1,""],["l",342.5,28.5,352,23,""],["l",361.5,28.5,364.8,26.6,""],["t",376.1,26.1,"Br","m"],["t",6,174,"(1)",""],["t",34,174,"HC\u2261C\u2296Na\u207A",""],["t",122,174,"(2)",""],["l",166,150,183.3,160,""],["l",168.2,155.3,177.7,160.8,""],["l",183.3,160,183.3,180,""],["l",183.3,180,166,190,""],["l",177.7,179.3,168.2,184.8,""],["l",166,190,148.7,180,""],["l",148.7,180,148.7,160,""],["l",152.1,175.5,152.1,164.5,""],["l",148.7,160,166,150,""],["l",183.3,160,200.6,150,""],["l",200.6,150,218,160,""],["t",226,174,"(3)",""],["l",290,170,280,187.3,""],["l",280,187.3,260,187.3,""],["l",275.5,183.9,264.5,183.9,""],["l",260,187.3,250,170,""],["l",250,170,260,152.7,""],["l",255.3,167.8,260.8,158.3,""],["l",260,152.7,280,152.7,""],["l",280,152.7,290,170,""],["l",279.3,158.3,284.8,167.8,""],["l",342,170,332,187.3,""],["l",332,187.3,312,187.3,""],["l",327.5,183.9,316.5,183.9,""],["l",312,187.3,302,170,""],["l",302,170,312,152.7,""],["l",307.3,167.8,312.8,158.3,""],["l",312,152.7,332,152.7,""],["l",332,152.7,342,170,""],["l",331.3,158.3,336.8,167.8,""],["l",290,170,302,170,""],["t",358,174,"(4)",""],["t",386,174,"C\u2084H\u2081\u2080",""]]},sfig:{w:360,h:190,alt:"Synthesis: CH3CHO reduced to ethanol (A), dehydrated to ethene (B), HBr gives bromoethane (C), which with bromobenzene and Na in dry ether (Wurtz-Fittig reaction) gives ethylbenzene (D).",d:[["t",4,44,"CH\u2083CHO",""],["l",58,36,108,36,"a"],["t",83,28,"(i) LiAlH\u2084","ms"],["t",83,54,"(ii) H\u2083O\u207A","ms"],["t",114,44,"CH\u2083CH\u2082OH",""],["t",150,68,"[A]","ms"],["l",184,36,236,36,"a"],["t",210,28,"H\u2082SO\u2084","ms"],["t",210,54,"\u0394","ms"],["t",242,44,"CH\u2082 = CH\u2082",""],["t",210,70,"Dehydration","ms"],["t",288,68,"[B]","ms"],["l",286,76,286,128,"a"],["t",278,104,"Bromination","es"],["t",294,104,"HBr","s"],["t",250,150,"CH\u2083CH\u2082\u2013Br",""],["t",286,180,"[C]","ms"],["l",240,142,148,142,"a"],["t",194,134,"Na/dry ether","ms"],["t",194,158,"Wurtz-Fittig","ms"],["t",194,170,"Reaction","ms"],["l",176,97,185.5,102.5,""],["l",178.2,100.5,181.5,102.4,""],["l",185.5,102.5,185.5,113.5,""],["l",185.5,113.5,176,119,""],["l",181.5,113.7,178.2,115.6,""],["l",176,119,166.5,113.5,""],["l",166.5,113.5,166.5,102.5,""],["l",168.4,109.9,168.4,106.1,""],["l",166.5,102.5,176,97,""],["l",185.5,102.5,188.8,100.6,""],["t",200.1,100.1,"Br","m"],["l",110,126,123.9,134,""],["l",112.2,130.5,118.9,134.4,""],["l",123.9,134,123.9,150,""],["l",123.9,150,110,158,""],["l",118.9,149.7,112.2,153.6,""],["l",110,158,96.1,150,""],["l",96.1,150,96.1,134,""],["l",98.9,145.9,98.9,138.1,""],["l",96.1,134,110,126,""],["l",123.9,134,137.7,126,""],["l",137.7,126,151.6,134,""],["t",100,180,"[D]","ms"]]}}]})();
